data.script:
const start = new Date(processData.startDate);
const end = new Date(processData.endDate);
let count = 0;
let current = new Date(start);

while (current <= end) {
  const dayOfWeek = current.getDay();
  if (dayOfWeek !== 0 && dayOfWeek !== 6) {
    count++;
  }
  current.setDate(current.getDate() + 1);
}

processData.calculatedLeaveDays = count;
processData.totalCalendarDays = Math.ceil((end - start) / (1000 * 60 * 60 * 24)) + 1;

const holidays = processData.publicHolidays || [];
let holidayCount = 0;

holidays.forEach(holiday => {
  const holidayDate = new Date(holiday.date);
  const dayOfWeek = holidayDate.getDay();
  if (dayOfWeek !== 0 && dayOfWeek !== 6) {
    holidayCount++;
  }
});

processData.publicHolidayCount = holidayCount;
processData.calculatedLeaveDays = processData.calculatedLeaveDays - holidayCount;

