  font-size: 14px;
  margin: 0;
}

.auth-footer a {
  color: var(--color-info);
  font-weight: 500;
  text-decoration: none;
}

.auth-footer a:hover {
  text-decoration: underline;
}

/* Sidebar Footer */
.nav-footer {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 16px 20px;
  border-top: 1px solid rgba(255,255,255,0.1);
  background: var(--color-primary);
}

.user-info {
  margin-bottom: 12px;
}

.user-name {
  color: rgba(255,255,255,0.9);
  font-size: 14px;
  font-weight: 500;
}

.logout-btn {
