}

.nav-icon {
  margin-right: 12px;
  font-size: 16px;
}

.nav-section {
  padding: 20px 20px 8px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: rgba(255,255,255,0.5);
}

/* Main Content */
.main-content {
  flex: 1;
  margin-left: 240px;
  padding: var(--spacing-section);
  background: var(--color-background);
  min-height: 100vh;
}

/* Page Container */
.page-container {
  max-width: var(--container-max-width);
  margin: 0 auto;
  padding-top: 32px;
}

/* Page Header */
.page-header {
