  border: 1px solid var(--color-card-border);
  border-radius: 12px;
  padding: 40px;
  box-shadow: 0 4px 24px rgba(0,0,0,0.08);
}

.auth-header {
  text-align: center;
  margin-bottom: 32px;
}

.auth-header h1 {
  font-size: 28px;
  font-weight: 700;
  color: var(--color-text);
  margin: 0 0 8px 0;
}

.auth-header p {
  color: var(--color-text-secondary);
  font-size: 15px;
  margin: 0;
}

.auth-error {
  background: #fef2f2;
  color: var(--color-error);
  padding: 12px 16px;
  border-radius: var(--radius-input);
  margin-bottom: 20px;
  font-size: 14px;
  border: 1px solid #fecaca;
}

.auth-form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.auth-form .form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.auth-form label {
  font-size: var(--font-size-label);
  font-weight: 500;
  color: var(--color-label);
}

.auth-form input {
  padding: 12px 16px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-input);
  font-size: 15px;
  transition: all 0.2s;
}

.auth-form input:focus {
  outline: none;
  border-color: var(--color-focus);
}

.auth-links {
  display: flex;
  justify-content: flex-end;
}

.auth-links a {
  color: var(--color-info);
  font-size: 14px;
  text-decoration: none;
}

.auth-links a:hover {
  text-decoration: underline;
}

.auth-btn {
  width: 100%;
  padding: 14px;
  background: var(--color-primary);
  color: white;
  border: none;
  border-radius: var(--radius-button);
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  margin-top: 8px;
}

.auth-btn:hover {
  opacity: 0.9;
}

.auth-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.auth-footer {
  text-align: center;
  margin-top: 24px;
  padding-top: 24px;
  border-top: 1px solid var(--color-card-border);
}

.auth-footer p {
  color: var(--color-text-secondary);
  font-size: 14px;
  margin: 0;
}

.auth-footer a {
  color: var(--color-info);
  font-weight: 500;
  text-decoration: none;
}

.auth-footer a:hover {
  text-decoration: underline;
}

/* Sidebar Footer */
.nav-footer {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 16px 20px;
  border-top: 1px solid rgba(255,255,255,0.1);
  background: var(--color-primary);
}

.user-info {
  margin-bottom: 12px;
}

.user-name {
  color: rgba(255,255,255,0.9);
  font-size: 14px;
  font-weight: 500;
}

.logout-btn {
  width: 100%;
  padding: 10px;
  background: transparent;
  border: 1px solid rgba(255,255,255,0.2);
  color: rgba(255,255,255,0.7);
  border-radius: var(--radius-button);
  cursor: pointer;
  font-size: 14px;
  transition: all 0.2s;
}

.logout-btn:hover {
  background: rgba(255,255,255,0.1);
  color: white;
  border-color: rgba(255,255,255,0.3);
}

/* Loading States */
.loading,
.app-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px;
  color: var(--color-text-secondary);
}

.app-loading {
  height: 100vh;
  background: var(--color-background);
}

.loading-spinner {
  width: 40px;
  height: 40px;
  border: 3px solid var(--color-card-border);
  border-top-color: var(--color-info);
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: 16px;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Empty State */
.empty-state {
  text-align: center;
  padding: 60px 20px;
  color: var(--color-text-secondary);
}

.empty-state h3 {
  margin-bottom: 8px;
  color: var(--color-label);
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--color-background);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb {
  background: var(--color-border);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--color-text-secondary);
}

/* Responsive */
@media (max-width: 768px) {
  .sidebar {
    width: 60px;
    padding: 10px 0;
  }

  .logo h2, .nav-section, .nav-link span {
    display: none;
  }

  .main-content {
    margin-left: 60px;
    padding: 16px;
  }

  .page-container {
    padding-top: 16px;
  }

  .page-header h1 {
    font-size: 22px;
  }

  .auth-card {
    padding: 24px;
  }
}

/* ============================================
